// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {EtherLotto} from "../src/EtherLotto.sol";

contract InvMutTest is Test {
    EtherLotto c;
    function setUp() public { c = new EtherLotto(); }

    function testFuzz_property(address payer) public {
        vm.assume(payer != address(0));
        vm.assume(payer != address(this));
        vm.deal(payer, 100 ether);

        uint before = address(c).balance;
        bool ok;

        uint ticket = 10;
        vm.prank(payer);
        try c.play{value: ticket}() {
            ok = true;
        } catch {
            ok = false;
        }

        assertTrue(ok && address(c).balance == before + ticket);
    }
}
